// Run first: the 10 nearest documents across all docs. The caller collects the returned ids and passes them as $ids to the next query.
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id, $d.title }
    order { nearest($d.embedding, $q) }
    limit 10
}
```

