// Run second: the caller passes the ids from the first query as $ids. This keeps only those documents in collection $coll and returns their titles.
query nearest_in_collection($ids: [String], $coll: String) {
    match {
        $d: Doc
        $d.id in $ids
        $c: Collection { slug: $coll }
        $d "in" $c
